/// Whether `token` occurs in `haystack` as a whole identifier.
///
/// The character before and after the match must not be ASCII alphanumeric or `_`, so
/// `scene.spawn` does not match inside `scene.spawn_primitive`. A trailing `.` still matches:
/// that is sentence punctuation, not a longer name.
pub fn mentions_token(haystack: &str, token: &str) -> bool {
    if token.is_empty() {
        return false;
    }
    let bytes = haystack.as_bytes();
    let needle = token.as_bytes();
    let mut from = 0;
    while let Some(rel) = haystack[from..].find(token) {
        let at = from + rel;
        let before_ok = at == 0 || !is_token_byte(bytes[at - 1]);
        let after = at + needle.len();
        let after_ok = after >= bytes.len() || !is_token_byte(bytes[after]);
        if before_ok && after_ok {
            return true;
        }
        // Step past the match's first character, not its first byte (a non-ASCII token).
        from = at + haystack[at..].chars().next().map_or(1, char::len_utf8);
    }
    false
}

fn is_token_byte(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || byte == b'_'
}

/// Whether any bundled [`GUIDE_TOPICS`] text names `method`.
///
/// This is the discovery entry `cargo xtask agent-coverage` requires: an agent can read the
/// method's name from `agent.guide` without opening the book.
pub fn guide_mentions(method: &str) -> bool {
    GUIDE_TOPICS
        .iter()
        .any(|topic| mentions_token(topic.text, method))
}

/// Old guide topic names that still resolve: `(alias, topic)`.
const GUIDE_ALIASES: &[(&str, &str)] = &[("tripod-gait", "procedural-gait")];

/// `agent.guide`: topic list, or one topic's text.
pub(crate) fn guide(params: &Value) -> Result<Value, RpcError> {
    let topics: Vec<Value> = GUIDE_TOPICS
        .iter()
        .map(|t| json!({ "topic": t.name, "summary": t.summary }))
        .collect();
    let Some(topic) = crate::params::opt_str(params, "topic")?.filter(|t| !t.is_empty()) else {
        return Ok(json!({ "topics": topics }));
    };
    let topic = GUIDE_ALIASES
        .iter()
        .find(|(alias, _)| *alias == topic)
        .map_or(topic, |(_, name)| *name);
    let Some(found) = GUIDE_TOPICS.iter().find(|t| t.name == topic) else {
        return Err(RpcError::not_found(
            format!("no guide topic {topic}"),
            format!(
                "known topics: {}",
                GUIDE_TOPICS.iter().map(|t| t.name).collect::<Vec<_>>().join(", ")
            ),
        ));
    };
    Ok(json!({ "topic": found.name, "summary": found.summary, "text": found.text }))
}

