    #[test]
    fn error_explanations_cover_every_code() {
        let explain = errors_explain(&json!({ "code": "F0012" })).expect("explains");
        assert_eq!(explain["jsonrpc"], crate::protocol::PERMISSION_DENIED);
        assert!(explain["fix"].as_str().unwrap_or("").contains("agent.toml"));
        assert!(errors_explain(&json!({ "code": "F9999" })).is_err());
        // Every code the runtime can emit has a long form.
        for (code, _, _, _) in error_explanations() {
            let explain = errors_explain(&json!({ "code": code })).expect("known code");
            assert_eq!(explain["code"], code);
        }
    }

